  // renderer/src/easter-egg.ts
  var MAX_STARS = 3e3;
  var HUE = 217;
  var TRAIL_ALPHA = 0.5;
  function mountNebula(container) {
    const canvas = document.createElement("canvas");
    canvas.id = "galaxy-canvas";
    canvas.style.cssText = "position:absolute;inset:0;width:100%;height:100%;display:block";
    container.appendChild(canvas);
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      container.innerHTML = "";
      return () => {
      };
    }
    let w = 0;
    let h3 = 0;
    let animId = 0;
    let mouseX = w / 2;
    let mouseY = h3 / 2;
    const glowCanvas = document.createElement("canvas");
    const glowCtx = glowCanvas.getContext("2d");
    glowCanvas.width = 100;
    glowCanvas.height = 100;
    const half = glowCanvas.width / 2;
    const gradient = glowCtx.createRadialGradient(half, half, 0, half, half, half);
    gradient.addColorStop(0.025, "#ccc");
    gradient.addColorStop(0.1, "hsl(" + HUE + ", 61%, 33%)");
    gradient.addColorStop(0.25, "hsl(" + HUE + ", 64%, 6%)");
    gradient.addColorStop(1, "transparent");
    glowCtx.fillStyle = gradient;
    glowCtx.beginPath();
    glowCtx.arc(half, half, half, 0, Math.PI * 2);
    glowCtx.fill();
    const stars = [];
    function maxOrbit(x, y) {
      const max = Math.max(x, y);
      const diameter = Math.round(Math.sqrt(max * max + max * max));
      return diameter / 2;
    }
    function resize() {
      const rect = container.getBoundingClientRect();
      w = rect.width;
      h3 = rect.height;
      const dpr = devicePixelRatio || 1;
      canvas.width = w * dpr;
      canvas.height = h3 * dpr;
      canvas.style.width = w + "px";
      canvas.style.height = h3 + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      stars.length = 0;
      const orbitMax = maxOrbit(w, h3);
      for (let i8 = 0; i8 < MAX_STARS; i8++) {
        const orbitRadius = Math.floor(Math.random() * (orbitMax + 1));
        stars.push({
          orbitRadius,
          radius: Math.floor(Math.random() * (orbitRadius - 60 + 1) + 60) / 8,
          orbitX: w / 2,
          orbitY: h3 / 2,
          timePassed: Math.floor(Math.random() * (MAX_STARS + 1)),
          speed: Math.floor(Math.random() * (orbitRadius + 1)) / 5e4,
          alpha: Math.floor(Math.random() * (10 - 2 + 1) + 2) / 10
        });
      }
      mouseX = w / 2;
      mouseY = h3 / 2;
    }
    function draw2() {
      ctx.globalCompositeOperation = "source-over";
      ctx.globalAlpha = TRAIL_ALPHA;
      ctx.fillStyle = "hsla(" + HUE + ", 64%, 6%, 2)";
      ctx.fillRect(0, 0, w, h3);
      ctx.globalCompositeOperation = "lighter";
      for (let i8 = 0, len = stars.length; i8 < len; i8++) {
        const s16 = stars[i8];
        const x = Math.sin(s16.timePassed) * s16.orbitRadius + mouseX;
        const y = Math.cos(s16.timePassed) * s16.orbitRadius + mouseY;
        if (Math.floor(Math.random() * 10) === 1 && s16.alpha > 0) {
          s16.alpha -= 0.05;
        } else if (Math.floor(Math.random() * 10) === 2 && s16.alpha < 1) {
          s16.alpha += 0.05;
        }
        ctx.globalAlpha = Math.max(0, Math.min(1, s16.alpha));
        ctx.drawImage(glowCanvas, x - s16.radius / 2, y - s16.radius / 2, s16.radius, s16.radius);
        s16.timePassed += s16.speed;
      }
      animId = requestAnimationFrame(draw2);
    }
    function onMouseMove(e2) {
      if (w === 0 || h3 === 0) return;
      const rect = container.getBoundingClientRect();
      mouseX = e2.clientX - rect.left;
      mouseY = e2.clientY - rect.top;
      mouseX = Math.max(0, Math.min(w, mouseX));
      mouseY = Math.max(0, Math.min(h3, mouseY));
    }
    function onMouseLeave() {
      mouseX = w / 2;
      mouseY = h3 / 2;
    }
    function cleanup2() {
      cancelAnimationFrame(animId);
      canvas.remove();
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseleave", onMouseLeave);
    }
    resize();
    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseleave", onMouseLeave);
    const ro2 = new ResizeObserver(() => resize());
    ro2.observe(container);
    draw2();
    return () => {
      ro2.disconnect();
      cleanup2();
    };
  }

